// Sentry Mate UI pack "Logbook": mock API.
//
// Everything the pages show comes through the functions exported here. They
// have the same names, arguments and result shapes as the real Sentry Mate
// JSON API (version 1), so switching to live data means replacing this one
// file with a thin fetch() wrapper. All values are SI-ish: kilometres, km/h,
// degrees Celsius, bar, kWh, Wh/km, epoch milliseconds. The pages convert to
// the viewer's units.
//
// The data is made up but deterministic: the same seed always gives the same
// fleet and the same history. Add ?cars=5000 to the page URL to try a bigger
// fleet.

export const API_VERSION = 1;
export const isMock = true;

const TZ = 'America/Chicago';
const DAY = 86400000;
const MIN = 60000;

/* ---------------------------------------------------------------- clock -- */

const partsFmt = new Intl.DateTimeFormat('en-US', {
  timeZone: TZ, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit',
});
// Central Time's offset from UTC, in minutes. It only changes on the hour, so
// it is worked out once per hour of time and reused.
const offsetCache = new Map();
function offsetMin(ms) {
  const k = Math.floor(ms / 3600e3);
  let o = offsetCache.get(k);
  if (o == null) {
    const p = {};
    const at = k * 3600e3;
    for (const x of partsFmt.formatToParts(new Date(at))) p[x.type] = x.value;
    o = Math.round((Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour % 24, +p.minute, +p.second) - at) / MIN);
    offsetCache.set(k, o);
  }
  return o;
}
function parts(ms) {
  const d = new Date(ms + offsetMin(ms) * MIN);
  return { y: d.getUTCFullYear(), m: d.getUTCMonth() + 1, d: d.getUTCDate(), hh: d.getUTCHours(), mm: d.getUTCMinutes(), ss: d.getUTCSeconds() };
}
/** Wall-clock time in America/Chicago to epoch ms. */
function local(y, m, d, hh = 0, mm = 0) {
  const guess = Date.UTC(y, m - 1, d, hh, mm);
  let t = guess - offsetMin(guess) * MIN;
  const o2 = offsetMin(t);
  if (guess - o2 * MIN !== t) t = guess - o2 * MIN;
  return t;
}
function dayKey(ms) {
  const p = parts(ms);
  return `${p.y}-${String(p.m).padStart(2, '0')}-${String(p.d).padStart(2, '0')}`;
}
function dayStart(key) {
  const [y, m, d] = key.split('-').map(Number);
  return local(y, m, d);
}
function addDays(key, n) {
  const [y, m, d] = key.split('-').map(Number);
  const t = new Date(Date.UTC(y, m - 1, d + n));
  return t.toISOString().slice(0, 10);
}
function weekday(key) {
  const [y, m, d] = key.split('-').map(Number);
  return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
}

// The demo is pinned to Monday, November 16, 2026, 7:24 PM Central so the
// sample day always reads the same; the clock then runs in real time.
const DEMO_NOW = local(2026, 11, 16, 19, 24) + 10000;
const T0 = (typeof performance !== 'undefined' ? performance.now() : 0);
function now() {
  return DEMO_NOW + Math.round((typeof performance !== 'undefined' ? performance.now() : 0) - T0);
}
const TODAY = dayKey(DEMO_NOW);

/* ------------------------------------------------------------ randomness -- */

function seedOf(str) {
  let h = 1779033703 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  h = Math.imul(h ^ (h >>> 16), 2246822507);
  h = Math.imul(h ^ (h >>> 13), 3266489909);
  return (h ^= h >>> 16) >>> 0;
}
function rng(str) {
  let a = seedOf(String(str));
  const next = () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
  next.range = (lo, hi) => lo + (hi - lo) * next();
  next.int = (lo, hi) => Math.floor(lo + (hi - lo + 1) * next());
  next.pick = (arr) => arr[Math.floor(next() * arr.length)];
  next.chance = (p) => next() < p;
  return next;
}
function weighted(r, table) {
  const total = table.reduce((s, [, w]) => s + w, 0);
  let x = r() * total;
  for (const [v, w] of table) { if ((x -= w) < 0) return v; }
  return table[table.length - 1][0];
}
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const round = (v, n = 0) => { const f = 10 ** n; return Math.round(v * f) / f; };

/* ------------------------------------------------------------- geometry -- */

function metresBetween(a, b) {
  const R = 6371008.8, toR = Math.PI / 180;
  const dLat = (b[1] - a[1]) * toR, dLon = (b[0] - a[0]) * toR;
  const s = Math.sin(dLat / 2) ** 2 + Math.cos(a[1] * toR) * Math.cos(b[1] * toR) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(s));
}
function cumulative(line) {
  const c = [0];
  for (let i = 1; i < line.length; i++) c.push(c[i - 1] + metresBetween(line[i - 1], line[i]));
  return c;
}
function pointAt(line, cum, x) {
  if (x <= 0) return line[0];
  const L = cum[cum.length - 1];
  if (x >= L) return line[line.length - 1];
  let lo = 0, hi = cum.length - 1;
  while (hi - lo > 1) { const mid = (lo + hi) >> 1; if (cum[mid] <= x) lo = mid; else hi = mid; }
  const f = (x - cum[lo]) / ((cum[hi] - cum[lo]) || 1);
  return [line[lo][0] + (line[hi][0] - line[lo][0]) * f, line[lo][1] + (line[hi][1] - line[lo][1]) * f];
}
function bearing(a, b) {
  const toR = Math.PI / 180;
  const y = Math.sin((b[0] - a[0]) * toR) * Math.cos(b[1] * toR);
  const x = Math.cos(a[1] * toR) * Math.sin(b[1] * toR) - Math.sin(a[1] * toR) * Math.cos(b[1] * toR) * Math.cos((b[0] - a[0]) * toR);
  return (Math.atan2(y, x) / toR + 360) % 360;
}
/** A street-grid path between two points, for places without stored road geometry. */
function gridRoute(a, b, seed) {
  const r = rng('grid:' + seed);
  const pts = [a];
  const legs = r.int(2, 4);
  let cur = a;
  for (let i = 1; i <= legs; i++) {
    const f = i / legs;
    const target = [a[0] + (b[0] - a[0]) * f + (i < legs ? r.range(-0.004, 0.004) : 0), a[1] + (b[1] - a[1]) * f + (i < legs ? r.range(-0.003, 0.003) : 0)];
    const corner = r.chance(0.5) ? [target[0], cur[1]] : [cur[0], target[1]];
    pts.push(corner, target);
    cur = target;
  }
  pts[pts.length - 1] = b;
  return pts;
}

