      vin: '5YJ3E1EB0MF000002', ratedFullKm: 568, usableKwh: 75, chargeLimit: 80, kg: 1840, owner: true,
      world: 'sf', places: SF_PLACES, baseId: 'home', software: '2026.38.4', odometerNowKm: 41207 * MI,
